def _decode(value: str) -> bytes:
    return zlib.decompress(base64.b64decode("".join(str(value).split())))


def patch(source_root: Path):
    source_root = Path(source_root).resolve()
    main = source_root / "app" / "src" / "main.py"
    voice = source_root / "app" / "src" / "voice_qwen.py"
    speech = source_root / "app" / "src" / "speech_input.py"
    board = source_root / "app" / "assets" / "whiteboard_template_v080.mp4"
    if not main.exists() or not voice.exists():
        raise FileNotFoundError("V0.8.0 base source missing")
    base = main.read_text(encoding="utf-8", errors="replace")
    if 'APP_VERSION = "0.7.7.12"' not in base:
        raise RuntimeError("V0.8.0 expected V0.7.7.12 expanded base source")

    main.write_bytes(_decode(MAIN_B64))
    voice.write_bytes(_decode(VOICE_B64))
    speech.write_bytes(_decode(SPEECH_B64))
    board.parent.mkdir(parents=True, exist_ok=True)
    board.write_bytes(_decode(BOARD_B64))

    py_compile.compile(str(main), doraise=True)
    py_compile.compile(str(voice), doraise=True)
    py_compile.compile(str(speech), doraise=True)

    m = main.read_text(encoding="utf-8")
    v = voice.read_text(encoding="utf-8")
    sp = speech.read_text(encoding="utf-8")
    checks = [
        'APP_VERSION = "0.8.0"',
        'class DialogueBoardOverlay(QWidget):',
        'class WhiteboardTemplateDialog(QDialog):',
        'def _begin_speech_session(self, inline_question=""):',
        'def _split_wake_phrase(text):',
        'Fun-ASR-Nano-2512',
        '回答结束后停留',
    ]
    for token in checks:
        if token not in m:
            raise RuntimeError(f"V0.8.0 main verification failed: {token}")
    for token in ('playback_started = Signal(str, int, str)', 'def warm_phrase_cache', 'def speak('):
        if token not in v:
            raise RuntimeError(f"V0.8.0 voice verification failed: {token}")
    for token in (
        'class SpeechInputService(QObject):', 'FSMN-VAD', 'Fun-ASR-Nano-2512',
        'remote_code=str(asr_model_dir / "model.py")', 'hotwords=[x for x in str(args.hotwords).split() if x]',
    ):
        if token not in sp:
            raise RuntimeError(f"V0.8.0 speech verification failed: {token}")
    if board.stat().st_size < 100000:
        raise RuntimeError("V0.8.0 whiteboard video is unexpectedly small")
    print("Patched XiaoMeili source to V0.8.0 voice interaction + universal whiteboard")


if __name__ == "__main__":
    if len(sys.argv) != 2:
        raise SystemExit("usage: patch_v080.py <source_root>")
    patch(Path(sys.argv[1]))